WITH valid AS (SELECT id, channel, ends_on, discount_pct, ROUND(discount_pct * 1.15, 2) AS discount_pct_adjusted, DATE_FORMAT(ends_on, 'yyyy-MM-dd') AS ends_on_label FROM promotions WHERE ends_on >= DATE '2023-05-26') SELECT src.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct AS promotion_discount_pct FROM valid src LEFT JOIN promotions pr ON src.channel <=> pr.channel AND src.ends_on >= pr.starts_on AND src.ends_on < pr.ends_on + INTERVAL '7' DAY;
